"""The revised building lesson: real Gaussian Splatting, not point-cloud display."""
def building(metrics):
    n=f"{metrics['gaussians']:,}".replace(',',' ');psnr=f"{metrics['mean_holdout_psnr_db']:.1f}".replace('.',',');ssim=f"{metrics['mean_holdout_ssim']:.3f}".replace('.',',')
    section='UYGULAMA 3 · 3D GAUSSIAN SPLATTING';slides=[]
    def add(title,message,notes,layout='visual',image=None,cards=(),sources=('gs','brush'),**kw):
        d=dict(title=title,message=message,notes=notes,layout=layout,cards=cards,section=section,sources=sources,**kw)
        if image:d['image']=image
        slides.append(d)
    add('Binayı bu kez dolu yüzeylerle görelim','AUTO ile veri topla; görüntülerden 3D Gaussian modeli öğren.',
        'Önceki sparse point cloud yalnız başlangıç geometrisini gösteriyordu. Bu revizyonda gerçek 3D Gaussian Splatting optimizasyonu kullanıyoruz. Konum, scale, rotation, opacity ve renk katsayıları fotoğraflara göre öğrenilir. Sonuç yalnız daha çok nokta çizmek değildir: kameraya yansıtılan Gaussian footprint’leri alpha compositing ile birleştirerek yeni bakışlar render edilir. Kaynak Gazebo bina mesh’i eğitim girdisi değildir. İlk olarak referans fotoğraf ile yeni modeli karşılaştırın.',layout='chapter',image='gaussian_final.png',chapter='03',subtitle='Bina çevresinde capture → reconstruction → novel-view rendering')
    add('Aynı binaya farklı açılardan bakmak','Görünmeyen yüzey fotoğraf verisi olmadan öğrenilemez.',
        'Bu üç kare iki AUTO orbit sırasında çekilmiş gerçek RGB fotoğraflarıdır. Cephelerde ortak ayrıntılar görünmeli; çatı da farklı yükseklikten gözlenmelidir. Doku, motion blur, camera pose ve overlap son kaliteyi etkiler. Çok fotoğraf, kötü açıyı otomatik düzeltmez. Görüntü seti 108 kare içerir; 94 train ve14 hold-out olarak ayrılır. Hold-out görüntüler sparse initialization ve gradient optimization aşamalarına verilmez.',layout='gallery',images=['gaussian_capture_a.png','gaussian_capture_b.png','gaussian_capture_c.png'],cards=[('Cephe A','Gerçek Gazebo RGB'),('Cephe B','Ortak feature’lar'),('Cephe + çatı','İkinci yükseklik')])
    add('Capture trajectory: iki AUTO orbit','26m radius;18 ve23m altitude;3m camera trigger.',
        'Çalışan AUTO uçuş dosyası korunur. Her orbit24açısal aralıklı waypoint’ten oluşur; iki yükseklik kamera açılarını çeşitlendirir. Araç3m/s görev hızında ilerler, mesafe tetiği fotoğraf komutlarını ArduPilot içinde üretir. Python burada rotayı sürmez. Sol grafikte iki tur yatayda üst üste gelir; sağdaki altitude grafiği iki yüksekliği ayırır. Mission Planner’da Create WP Circle ile benzer başlangıç rotası üretilebilir; yükseklik, yarıçap ve ROI daha sonra kontrol edilir.',layout='photo',image='building_ucus.png',cards=[('AUTO trajectory','R=26m ·18/23m'),('Camera trigger','DO_SET_CAM_TRIGG_DIST=3m'),('Veri','108 gerçek RGB fotoğraf')],sources=('commands','roi'))
    add('Gimbal sürekli ROI’ye bakar','Flight trajectory ve camera pointing iki ayrı görev işlevi.',
        'Şemada kameralar orbit üzerinde ilerlerken görüş doğrultuları aynı ROI noktasına gider. DO_SET_ROI hedefi home’a göre7m yükseklikte seçilmiştir. ArduPilot mount çıkışları kamera yönünü günceller; Python kare başına açı komutu yollamaz. Buradaki servo gimbal ideal kinematiktir; latency ve inertia modellenmez. Gerçek kayıtta ROI doğrultu hatası medyan0,318derece ve95.persentil0,724derecedir. İdeal gimbalın doğru bağlandığı kanıtlanır; donanım doğruluğu iddia edilmez.',image='ex_roi.png',sources=('mount','roi'))
    add('Pipeline: pose → initialization → training','Bu simülasyonda camera pose biliniyor; saha akışında SfM gerekir.',
        'Gerçek saha iş akışında COLMAP veya benzeri SfM aracı intrinsics, camera poses ve başlangıç point cloud üretir. Bu öğretim örneğinde simülatörden kaydedilmiş kalibre camera pose kullanılır. Image matching ve triangulation ise yalnız94train fotoğrafında yapılır.1298görüntü kaynaklı sparse nokta initialization için kullanılır. Daha sonra Brush bu Gaussians’ları tüm train görüntülere göre optimize eder. Kaynak bina mesh’i veya derinlik sensörü okunmaz.',layout='flow',cards=[('RGB + poses','Gazebo kayıtları'),('Sparse init','Train-only SIFT'),('3DGS training','Brush · gradient update'),('Novel view','Hold-out render')],sources=('sfm','gs','brush'))
    add('Sparse point cloud artık başlangıç verisi','Eksik yüzeyi nokta sayısını artırarak değil, görüntü loss’u ile tamamlıyoruz.',
        'Sparse initialization SIFT eşleşmesi, RANSAC, triangulation ve reprojection error filtresinden üretilir. Önceki1787noktalı çıktı burada nihai ürün olarak sunulmaz. Yeni temiz train/hold-out ayrımında1298train-only başlangıç noktası vardır. Bu daha küçük başlangıç kümesi bile Gaussian optimization için yeterli referans sağlar. Modelin gerçek gelişimi render edilen görüntü ile referans fotoğraf arasındaki farkın azaltılmasından gelir.',layout='compare',images=['bina_3d.png','gaussian_final.png'],cards=[('Sparse initialization','Geometrik başlangıç; nihai ürün değil.'),('Optimized 3D Gaussians','Yüzey görünüşünü veren radiance representation.')])
    add('Bir Gaussian hangi parametrelere sahip?','Position, scale, rotation, opacity ve color birlikte öğrenilir.',
        'Bir Gaussian’ı uzayda yönlenmiş yumuşak bir elipsoid olarak düşünün. Merkez μ, üç eksenli scale ve rotation covariance’ı belirler. Opacity görünürlüğü, renk ve spherical harmonics katsayıları görünüşü belirler. Final modelde SH degree2kullanıldı. Elipsoidler kapalı katı yüzeyler değildir; görüntü oluşturmak için sürekli ağırlık fonksiyonlarıdır. Şema öğretim çizimidir, gerçek modeldeki bir Gaussian’ın ölçümü değildir.',image='ex_gaussian.png')
    add('3D Gaussian ekranda bir splat olur','Camera projection, elipsoidi piksel düzleminde footprint’e dönüştürür.',
        'K ve camera pose ile Gaussian merkezi kameraya taşınır. Projection Jacobian,3Dcovariance’ı yaklaşık2Delliptik covariance’a dönüştürür. Böylece aynı Gaussian farklı bakışlarda farklı boyut ve yönelimle görünür. Her piksel Gaussian merkezine göre ağırlık alır. Splatting, normal point cloud’daki sabit büyüklükte nokta işaretlerinden bu yönüyle ayrılır. Bu derste türevi ezberletmek yerine 3D→2D→renk birikimi ilişkisini gösterin.',image='ex_splat_projection.png')
    add('Alpha compositing ve depth order','Öndeki splat, arkadakinin katkısını azaltır.',
        'Gaussian’lar görüntüde örtüşür. Front-to-back compositing sırasında birikmiş transmittance, arkadaki renk katkısını ağırlıklandırır. Örneğin yüzde50opacity’li iki katmanın etkisi düz renk ortalaması değildir; sıralama önemlidir. Bu nedenle visibility-aware rendering gerekir. Slayttaki iki panel yalnız compositing mantığını anlatır; gerçek binanın iki render’ı değildir. Rendering’in fiziksel yüzey mesh’i yerine optik katkı modeli kullandığını vurgulayın.',image='ex_alpha.png')
    add('Training loop: render, compare, update','Amaç referans fotoğraflara benzeyen render üretmek.',
        'Her training step bir train camera seçer, mevcut Gaussians’ları render eder, referans RGB ile L1 ve SSIM tabanlı loss hesaplar ve gradient ile parametreleri günceller. Paneldeki görüntü eğitimden ayrı hold-out değerlendirme görüntüsüdür; mekanizmayı göstermek için final render ile referans farkı yan yana verilmiştir. Hold-out görüntünün loss’u optimizer’a geri verilmez. Difference paneli görünürlük için4kat büyütülmüştür; yeni ayrıntı veya sahte hata üretilmemiştir.',image='ex_training_loop.png')
    add('Densification: ayrıntı gereken yerde büyüme','Gaussian yoğunluğu training sırasında uyarlanır.',
        'Başlangıç noktaları bütün dokuyu açıklayamaz. Brush0.3MCMC benzeri adaptive densification kullanır; growth eşiği, seçilen oran ve max-splats sınırı yoğunluğu kontrol eder. Bu şema genel ilkeyi gösterir; Brush’ın birebir her kernel adımını veya gerçek nokta sayısını resmetmez. Gerçek referans koşusunda max45000Gaussians sınırı kullanılır. Daha çok Gaussian tek başına kalite kanıtı değildir; hold-out görünüş ve floaters da kontrol edilir.',image='ex_densification.png')
    add('Aynı run:1 000 →3 000 →6 000 steps','Checkpoint render’ları aynı hold-out camera’dan karşılaştırılıyor.',
        'Üç panel final training koşusunun gerçek checkpoint çıktılarıdır. Aynı camera ve aynı input karşılaştırıldığı için iyileşmeyi doğrudan görebiliriz. Pencere kenarları, çatı ve bina siluetini gözleyin. Step sayısı ilerlerken gereksiz floaters veya aşırı bulanıklık kalırsa yalnız süreyi artırmak yerine veri kalitesine dönmek gerekir. Bu run Intel UHD730bulunan Windows bilgisayarda CUDA kurulmadan çalıştırılmıştır.',image='ex_training_progress.png')
    add('Hold-out view: görmediği açıyı render et','14görüntü initialization ve training dışında bırakıldı.',
        'Her8.kare evaluation için ayrıldı. Bu görüntüler sparse initialization’a da verilmedi; böylece görüntü veya renk başlangıcından leakage önlendi. Camera pose evaluation render için bilinir; bu bilinen-pose deneyinin parçasıdır.94train görüntüyle öğrenilen model,14ayrılmış açıdan render edilir. Bu bir gerçek dünya genel performans benchmarkı değildir; aynı simülasyon sahnesinde genellemeyi kontrol eden bir deneydir.',image='ex_holdout.png')
    add('Reference RGB ile Gaussian render','Aynı camera; solda gerçek sensör kaydı, sağda model.',
        'Soldaki fotoğraf Gazebo kamerasından, sağdaki yalnız eğitilmiş Gaussian parametrelerinden üretilmiştir. Sağ görüntüde kaynak bina mesh’i kullanılmaz. Pencereler, çatı kenarı, giriş ve gölgeyi kıyaslayın. Sahnenin uzak zemininde daha fazla blur olabilir; kameranın gördüğü airframe parçaları floaters’a yol açabilir. Öğrenciden yalnız güzel görünen yüzeyi değil kalan farkları da göstermesini isteyin.',layout='compare',images=['gaussian_reference.png','gaussian_final.png'],cards=[('Reference · hold-out RGB','Optimizasyona verilmemiş gerçek görüntü.'),('3DGS render','Öğrenilmiş Gaussian modelinin görünüşü.')])
    add('Sonuç: kullanılabilir 3D Gaussian model',f'{n}Gaussians · hold-out PSNR{psnr}dB · SSIM{ssim}.',
        f'Final model6bin training step sonunda{n}Gaussians içeriyor.14hold-out görüntüde ortalama PSNR{psnr}dB ve SSIM{ssim} ölçüldü. PSNR piksel hatasını, SSIM yerel yapı benzerliğini özetler. Bunlar geometric accuracy, ölçüm hatası veya bina boyut doğruluğu değildir. Render görselleri ve metrik JSON birlikte saklanır. Model PLY dosyasında opacity, rotation, scale ve SH katsayıları vardır; sıradan XYZRGB point cloud dosyası değildir.',layout='spotlight',image='gaussian_final.png',stats=[(n,'trained Gaussians'),(psnr+' dB','mean hold-out PSNR'),(ssim,'mean hold-out SSIM')])
    add('Tek model, farklı viewpoint’ler','Brush viewer’da orbit ve zoom ile bütün cepheleri inceleyin.',
        'Paneller aynı final Gaussian checkpoint’inin üç farklı hold-out camera’dan gerçek render’larıdır; viewer ekran görüntüsü değildir.3D_Goster.cmd paylaşılan Gaussian PLY modelini resmî Brush viewer’da açar. Çatı üstünü, yan cepheleri ve floaters’ı inceleyin; tek bir render’a güvenmeyin. Bu bir Gazebo sahne dosyasının yeniden açılması değildir. Otomatik testte native viewer penceresi açıldı; masaüstü oturumunda ekran yakalama doğrulanamadığından sunumda yalnız gerçek render’lar gösterilir. EXE veya ZIP yeniden dağıtılmaz.',layout='gallery',images=['gaussian_render_a.png','gaussian_render_b.png','gaussian_render_c.png'],cards=[('View A','Final Gaussian render'),('View B','Farklı cephe'),('View C','İkinci yükseklik')],sources=('brush',))
    add('Gaussian model, mesh ve point cloud farklıdır','Görsel olarak dolu görünmek, watertight mesh üretmek değildir.',
        'Üç çıktı tipini doğru adlandırın. Point cloud örneklenmiş konumları gösterir. Gaussian model optimize edilmiş radiance primitive’leriyle görüntü render eder. Mesh ise vertex ve triangle bağlantılarıyla yüzey temsilidir. Bu haftanın yeni çıktısıGaussian PLY’dir; CAD, kapalı yüzey veya hacim ölçümü için doğrudan mesh kabul edilmez. İleri iş akışlarında meshing veya surface reconstruction ayrıca gerekir.',layout='table',headers=['Temsil','Dosyadaki temel bilgi','Bu haftadaki rol'],rows=[['Sparse point cloud','XYZ + RGB','Train-only initialization'],['3D Gaussian Splatting','XYZ + scale + rotation + opacity + SH','Yeni ana3Dçıktı'],['Triangle mesh','Vertex + face + texture','Bu akışta üretilmiyor'],['Kontrol','Hold-out render + serbest viewer','Görünüş ve floaters kontrolü']])
    add('Öğrencinin3Düretim adımları','Bina AUTO uçuşundan sonra3D_Uret.cmd çalıştırılır.',
        'Önce menü3ile bina görevini tamamlayın. Sonra3D_Uret.cmd dosyasını açıp terminalde gösterilen uçuş klasörünü yapıştırın. Araç indirme, dataset export, train-only initialization, training ve değerlendirme otomatik yürür. Bu sırada uçuş komutu gönderilmez. Training süresi donanıma bağlıdır; derste önce hazır model3D_Goster.cmd ile incelenebilir. İsteyen öğrenci aynı dosyalardan kendi modelini yeniden üretir. Installer SHA256 ile resmî Brush release’ini doğrular.',layout='flow',cards=[('AUTO capture','Menü3 → görev → LAND'),('3D_Uret.cmd','RESULT klasörünü yapıştır'),('Training','Checkpoint + hold-out eval'),('Viewer','Orbit → zoom → incele')],sources=('repo','brush'))
    add('Kaliteyi artırmak için önce veriye bakın','Blur, düşük overlap ve occlusion daha çok step ile her zaman düzelmez.',
        'İlk örnek dolu bir bina görünüşü üretse de kamera önündeki airframe parçaları, tekdüze duvar ve uzaktaki zemin kalite sınırlarıdır. Daha iyi capture için gövdeyi görmeyen kamera yerleşimi, farklı yükseklik ve yeterli overlap gerekir. Gerekirse image mask yalnız gerçek RGB’den hazırlanarak occluder’lar training loss’undan çıkarılır; bu referans koşusunda mask kullanılmadı. Parametre değiştirmeden önce reference fotoğrafı büyütün. Yalnız Gaussians sayısını büyütmek veri hatasını çözmez.',layout='photo',image='gaussian_reference.png',cards=[('Capture','Overlap + net görüntü + angle çeşitliliği'),('Occlusion','Airframe / ağaç / gölge kontrolü'),('Evaluation','Novel-view render ve floaters')])
    add('Uygulama: capture değişsin, AUTO sınırı kalsın','Tek değişkenle veri toplayın; aynı hold-out mantığıyla karşılaştırın.',
        'Öğrenci referans görevini koruyup bir kopyada yalnız camera trigger mesafesini veya ikinci orbit yüksekliğini değiştirir. Uçuş yine AUTO kalkıştan LAND’e kadar ilerlemelidir. Sonra aynı training budget ile yeniden model üretir. Karşılaştırmada capture sayısı, render ayrıntısı, floaters, PSNR ve SSIM birlikte yorumlanır. Camera pose simülatörden biliniyorsa bunun raporda açıkça yazılması gerekir. Son ürün Gaussian PLY ve bir reference/render karşılaştırmasıdır.',layout='cards',cards=[('Planla','Orbit veya trigger’da tek değişken.'),('Üret','Aynı training budget ile3DGS.'),('Karşılaştır','Hold-out view + viewer + artefact’lar.')],sources=('commands','brush'))
    assert len(slides)==20
    return slides
